<?php
namespace App\Http\Controllers;
use App\Models\{RoomType,Reservation,Setting,User};
use App\Services\{TrainingPolicy,RecommendedBooking,HotelService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class GuestBookingController extends Controller {
 public function session(Request $q){return ['csrf'=>csrf_token(),'user'=>$q->user(),'guest'=>$q->user()?->role==='guest'?$q->user()->guest:null];}
 public function services(Request $q){if($q->isMethod('post')){abort_unless($q->user()?->role==='admin',403);$v=$q->validate(['services'=>'present|array|max:30','services.*.id'=>'required|string|distinct|max:40|regex:/^[a-zA-Z0-9_-]+$/','services.*.name'=>'required|string|max:100','services.*.description'=>'nullable|string|max:500','services.*.price'=>'required|numeric|min:0|max:100000','services.*.active'=>'required|boolean']);Setting::updateOrCreate(['key'=>'booking_services'],['value'=>$v['services']]);HotelService::audit('booking-services.updated','catalog');}return array_values(array_filter(Setting::where('key','booking_services')->first()?->value??[],fn($s)=>$q->user()?->role==='admin'||($s['active']??true)));}
 private function values(Request $q):array{return $q->validate(['arrival'=>'required|date|after_or_equal:today','departure'=>'required|date|after:arrival|before_or_equal:'.today()->addYears(2)->toDateString(),'promo_code'=>'nullable|string|max:40','rooms'=>'required|array|min:1|max:5','rooms.*.room_type_id'=>'required|exists:room_types,id','rooms.*.adults'=>'required|integer|min:1|max:20','rooms.*.children'=>'required|integer|min:0|max:20','rooms.*.child_ages'=>'present|array|max:20','rooms.*.child_ages.*'=>'required|integer|min:0|max:17','rooms.*.breakfast'=>'required|in:None,Buffet,Plated','rooms.*.breakfast_pax'=>'required|integer|min:0|max:40','rooms.*.services'=>'present|array|max:30','rooms.*.services.*.id'=>'required|string|max:40','rooms.*.services.*.quantity'=>'required|integer|min:1|max:20']);}
 private function prices(array $v):array{
  $n=(int)\Carbon\Carbon::parse($v['arrival'])->diffInDays($v['departure']);if($n>90)HotelService::fail('Maximum training stay is 90 nights.');
  $requested=collect($v['rooms'])->countBy('room_type_id');foreach($requested as $id=>$count){$type=RoomType::findOrFail($id);$stock=$type->rooms()->where('out_of_service',false)->count();for($day=\Carbon\Carbon::parse($v['arrival']);$day->lt(\Carbon\Carbon::parse($v['departure']));$day->addDay()){$used=Reservation::where('room_type_id',$id)->whereNotIn('status',['Cancelled','Checked-out'])->where('arrival','<=',$day->toDateString())->where('departure','>',$day->toDateString())->count();if($used+$count>$stock)HotelService::fail('Not enough '.$type->name.' rooms for these dates. Please change your selection.');}}
  $rooms=[];foreach($v['rooms'] as $room){if(count($room['child_ages'])!==$room['children'])HotelService::fail('Enter the age of each child.');if(count(array_unique(array_column($room['services'],'id')))!==count($room['services']))HotelService::fail('Select each additional service once.');$type=RoomType::findOrFail($room['room_type_id']);$price=TrainingPolicy::quote($type,[...$room,'promo_code'=>$v['promo_code']??null],$n);$rooms[]=['type'=>$type->name,'room_type_id'=>$type->id,'pricing'=>$price];}
  return ['rooms'=>$rooms,'nights'=>$n,'total'=>round(collect($rooms)->sum('pricing.total'),2),'deposit_due'=>round(collect($rooms)->sum('pricing.deposit_due'),2)];
 }
 public function quote(Request $q){return $this->prices($this->values($q));}
 public function book(Request $q){abort_unless($q->user()?->role==='guest',403);$v=$this->values($q);$details=$q->validate(['reference'=>'required|uuid','name'=>'required|string|max:180','email'=>'required|email|max:254','email_confirmation'=>'required|same:email','country'=>'required|string|max:100','address'=>'required|string|max:255','city'=>'required|string|max:100','phone'=>'required|string|max:30','requests'=>'nullable|string|max:2000','privacy'=>'accepted','payment_choice'=>'required|in:Later,Deposit,Full']);$details['email']=strtolower(trim($details['email']));abort_unless($details['email']===strtolower($q->user()->email),422,'Use your signed-in account email for this reservation.');$details['phone']=AuthController::phone($details['phone']);if(!preg_match('/^\+639\d{9}$/',$details['phone']))HotelService::fail('Enter a valid Philippine mobile number.');
  return DB::transaction(function()use($q,$v,$details){User::whereKey($q->user()->id)->lockForUpdate()->first();$hash=hash('sha256',json_encode([$v,$details]));$old=DB::table('guest_booking_requests')->where('reference',$details['reference'])->first();if($old){abort_unless($old->user_id===$q->user()->id&&hash_equals($old->payload_hash,$hash),409,'This booking reference was already used.');return response()->json(['reservations'=>Reservation::whereIn('id',json_decode($old->reservation_ids,true))->get(),'replayed'=>true],200);}
  RoomType::whereIn('id',array_column($v['rooms'],'room_type_id'))->orderBy('id')->lockForUpdate()->get();$this->prices($v);$guest=$q->user()->guest;$guest->update(['name'=>$details['name'],'phone'=>$details['phone'],'address'=>$details['address'].', '.$details['city'].', '.$details['country']]);$created=[];foreach($v['rooms'] as $room){$created[]=RecommendedBooking::create([...$room,'arrival'=>$v['arrival'],'departure'=>$v['departure'],'promo_code'=>$v['promo_code']??null,'requests'=>$details['requests']??null,'booking_details'=>['country'=>$details['country'],'address'=>$details['address'],'city'=>$details['city'],'phone'=>$details['phone'],'name'=>$details['name'],'child_ages'=>$room['child_ages'],'privacy_accepted_at'=>now()->toIso8601String(),'payment_choice'=>$details['payment_choice'],'booking_reference'=>$details['reference']]],$guest->id,false);}
  DB::table('guest_booking_requests')->insert(['user_id'=>$q->user()->id,'reference'=>$details['reference'],'payload_hash'=>$hash,'reservation_ids'=>json_encode(array_map(fn($r)=>$r->id,$created)),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['reservations'=>$created],201);
 });}
}
